  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_student_job` (`job_id`,`student_id`),
  KEY `idx_applications_job_id` (`job_id`),
