INSERT INTO `applications` VALUES (1,1,1,'I am eager to apply for the Computer Lab Technical Assistant position. As a 2nd year BS Information Systems student at KLD, I have solid experience troubleshooting PC hardware, setting up local area networks, and installing development environments. I am enthusiastic about supporting fellow KLD students and keeping our laboratories running smoothly.','[\"Mon - Afternoon (1PM\\u20135PM)\",\"Wed - Afternoon (1PM\\u20135PM)\",\"Fri - Morning (8AM\\u201312NN)\"]','Juan_Dela_Cruz_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','interview_scheduled','2026-09-28','02:00 PM','KLD Tech Building, Room 305 (MIS Office)','Strong background in PC troubleshooting. Scheduled for face-to-face technical interview.','2026-08-22 14:30:00','2026-08-24 10:00:00'),(2,2,1,'I would like to offer my clerical and database encoding skills to the Office of the University Registrar at KLD. I am proficient in MS Excel spreadsheets and data archiving.','[\"Tue - Morning (8AM\\u201312NN)\",\"Thu - Morning (8AM\\u201312NN)\"]','Juan_Dela_Cruz_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','interview_scheduled','2026-09-29','02:00 PM','KLD Admin Building, 1st Floor, Room 102','Application received, awaiting registrar committee evaluation.','2026-08-24 09:15:00','2026-08-26 08:40:13'),(3,3,2,'I am applying for the Library Aid role. I spend a lot of time in the KLD library, have high attention to detail, and can commit to morning shifts.','[\"Mon - Morning (8AM\\u201312NN)\",\"Wed - Morning (8AM\\u201312NN)\"]','Maria_Santos_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-08-23','10:00 AM','KLD Main Library 2nd Floor Office','Excellent communication skills and schedule fit. Officially approved for 1st Semester duty.','2026-08-20 11:00:00','2026-08-24 16:20:00'),(4,9,1,'I am interested in assisting the Athletics office with sports equipment and gym floor monitoring. I have experience in logistics and event setup.','[\"Fri - Afternoon (1PM\\u20135PM)\"]','Juan_Dela_Cruz_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','pending',NULL,NULL,NULL,'Dossier under review by coach Belmonte.','2026-08-28 16:00:00','2026-08-28 16:00:00'),(5,1,12,'Good day! As a 1st year BSIT student, I am very enthusiastic about hands-on laboratory hardware and networking. I want to assist upperclassmen and laboratory engineers while supporting my college expenses.','[\"Tue - Afternoon (1PM\\u20135PM)\",\"Thu - Afternoon (1PM\\u20135PM)\"]','Joshua_Garcia_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','pending',NULL,NULL,NULL,'Received application. Resume passed initial pre-screening.','2026-09-05 10:15:00','2026-09-05 10:15:00'),(6,2,13,'As an Accountancy junior, meticulous record-keeping and data integrity are my strongest skills. I can assist the Registrar with student document archiving and spreadsheet audit trails.','[\"Mon - Afternoon (1PM\\u20135PM)\",\"Wed - Afternoon (1PM\\u20135PM)\",\"Fri - Afternoon (1PM\\u20135PM)\"]','Camille_Del_Rosario_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-12','01:30 PM','Admin Building, Room 102','Candidate has outstanding analytical precision and GWA. Approved for 15 hours weekly duty.','2026-09-02 09:00:00','2026-09-14 11:30:00'),(7,14,13,'I am applying for the Scholarship Records & Encoding Clerk role. I am proficient in Google Sheets formulas, pivot tables, and verifying documentary prerequisites.','[\"Fri - Afternoon (1PM\\u20135PM)\"]','Camille_Del_Rosario_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-15','10:00 AM','Admissions & Scholarship Office, Window 4','Hired to assist during upcoming LGU scholarship renewal rush.','2026-09-08 14:20:00','2026-09-16 15:00:00'),(8,9,14,'I have participated in collegiate basketball and understand the care required for athletics facilities and hardwood court maintenance. Ready for afternoon shifts.','[\"Sat - Whole Day (8AM\\u20135PM)\"]','Ethan_Vance_Reyes_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','interview_scheduled','2026-09-28','11:00 AM','University Gymnasium, Coach Office 101','Strong physical aptitude and availability for weekend intramural games. Scheduled for interview.','2026-09-12 11:45:00','2026-09-18 16:20:00'),(9,6,15,'Hello! As a Communication major, visual storytelling is my passion. Attached is my portfolio showcasing reels and graphics created for campus student organizations.','[\"Mon - Morning (8AM\\u201312NN)\",\"Thu - Afternoon (1PM\\u20135PM)\"]','Sofia_Mendoza_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-10','03:00 PM','Dasma Creative Media Studio, Suite 201','Exceptional portfolio quality. Officially brought on board as Junior Content Creator.','2026-09-01 13:00:00','2026-09-11 17:00:00'),(10,16,15,'Applying to coordinate social media graphic posts and layout design. Excited to contribute to KLD\'s digital presence.','[\"Thu - Afternoon (1PM\\u20135PM)\"]','Sofia_Mendoza_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-14','02:00 PM','Creative Hub Center','Assigned to the campus campaign visual rollout team.','2026-09-07 10:30:00','2026-09-15 14:15:00'),(11,7,16,'As a Hospitality Management major, customer warmth, beverage preparation, and dining sanitation are part of my core training. Excited to brew great coffee for our KLD community!','[\"Wed - Morning (8AM\\u201312NN)\",\"Sat - Morning (8AM\\u201312NN)\"]','Mark_Dave_Bautista_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','accepted','2026-09-09','09:30 AM','Campus Cafe Counter, Student Pavilion','Completed food safety orientation and barista espresso training. Start date approved.','2026-09-03 14:00:00','2026-09-10 16:45:00'),(12,13,17,'As a Psychology student, I want to actively support fellow students facing academic stress and life transitions. I will maintain absolute confidentiality at the Guidance frontdesk.','[\"Mon - Morning (8AM\\u201312NN)\",\"Tue - Morning (8AM\\u201312NN)\"]','Angela_Nicole_Cruz_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-11','10:30 AM','Guidance Center, Room 204','Very mature, professional demeanor with deep understanding of ethical confidentiality. Hired as Peer Facilitator.','2026-09-04 15:30:00','2026-09-12 11:00:00'),(13,11,18,'I have consistently achieved 1.25 in Data Structures, Algorithms, and Advanced Java. I enjoy mentoring freshmen and helping them overcome the fear of pointers and recursion.','[\"Mon - Afternoon (1PM\\u20135PM)\",\"Wed - Afternoon (1PM\\u20135PM)\"]','Gabriel_Tan_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','accepted','2026-09-08','04:00 PM','MIS Center, Room 305','Outstanding technical exam score (98/100). Approved as Lead Peer Tutor for DSA.','2026-09-02 16:15:00','2026-09-09 10:00:00'),(14,5,18,'Applying for the Junior Web Developer position. I have built full-stack web applications and automated QA pipelines using Playwright and Jest.','[\"Fri - Afternoon (1PM\\u20135PM)\"]','Gabriel_Tan_Resume.pdf','Juan_Dela_Cruz_StudyLoad.pdf','interview_scheduled','2026-09-29','03:00 PM','TechVanguard Solutions, Suite 401','Impressive GitHub repositories. Technical interview scheduled with lead architect.','2026-09-10 11:20:00','2026-09-17 14:00:00'),(15,12,11,'As a Level III Nursing student, I am well-versed in aseptic technique, clinical manikin setup, and hospital simulation ward maintenance. I want to assist our instructors during clinical laboratory hours.','[\"Mon - Morning (8AM\\u201312NN)\",\"Wed - Morning (8AM\\u201312NN)\"]','Bea_Alonzo_Resume.pdf','Maria_Santos_StudyLoad.pdf','accepted','2026-09-07','08:30 AM','Science & Allied Health Building, Room 301','Top student in Medical-Surgical nursing rotation. Assigned to Simulation Ward 202 duty.','2026-09-03 09:15:00','2026-09-08 14:30:00'),(16,18,11,'Offering my clinical skills to assist campus nurses during clinic consultations and student annual medical checkups.','[\"Fri - Morning (8AM\\u201312NN)\"]','Bea_Alonzo_Resume.pdf','Maria_Santos_StudyLoad.pdf','interview_scheduled','2026-09-30','09:00 AM','Campus Health Clinic, Room 105','Passed