INSERT INTO `categories` VALUES (1,'IT & Technical Support','it-technical-support','bi-laptop','IT lab maintenance, technical troubleshooting, network setup, compiler installations, and student workstation support.','kld-green','Most In-Demand','bi-fire',4,'₱85 - ₱120 / hr','assets/img/categories/cat-tech.jpg','[\"Computer Lab Assistant\",\"Network Technician\",\"MIS Helpdesk\",\"Frontend Assistant\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12'),(2,'Library Services','library-services','bi-book','Book cataloging, barcode circulation scanning, digital archive indexing, OPAC search assistance, and study hub oversight.','kld-green','Quiet Study Hub','bi-bookmark-star',1,'₱80.00 / hr','assets/img/categories/cat-library.jpg','[\"Digital Cataloger\",\"Circulation Desk Aid\",\"Archive Assistant\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12'),(3,'Administrative Clerk','administrative-clerk','bi-folder2-open','Student 201 records processing, registrar encoding, document sorting, and courteous frontline campus queue assistance.','kld-green','Campus Admin','bi-building-check',6,'₱80 - ₱95 / hr','assets/img/categories/cat-admin.jpg','[\"Records Clerk\",\"Data Encoder\",\"Frontline Desk Aid\",\"Barista\",\"Bookstore Aide\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12'),(4,'Science & Computer Lab Assistant','science-computer-lab-assistant','bi-radioactive','Science & medical laboratory apparatus preparation, glassware autoclaving, chemical inventory logging, and safety protocol enforcement.','kld-green','Science & Health','bi-moisture',3,'₱85.00 / hr','assets/img/categories/cat-lab.jpg','[\"Medical Lab Aid\",\"Nursing Sim Lab Aide\",\"Apparatus Prep\",\"Clinic Support\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12'),(5,'Peer Tutor','peer-tutor','bi-mortarboard','1-on-1 and small group academic tutoring in mathematics, coding algorithms, discrete structures, sciences, and exam preparation.','kld-green','Academic Mentoring','bi-award-fill',3,'₱100.00 / hr','assets/img/categories/cat-tutor.jpg','[\"Math & Calc Tutor\",\"DSA Programming Mentor\",\"Peer Coach\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12'),(6,'Sports & Athletics Aide','sports-athletics-aide','bi-trophy','Gymnasium equipment logistics, scorekeeping, court maintenance, intramural tournament assistance, and athletics facility safety.','kld-green','Campus Athletics','bi-trophy-fill',3,'₱85.00 / hr','assets/img/categories/cat-sports.jpg','[\"Equipment Custodian\",\"Tournament Scorekeeper\",\"Field Marshal\"]',0,NULL,'2026-09-30 20:24:12','2026-09-30 20:24:12');
