INSERT INTO `jobs` VALUES (1,'Computer Lab Technical Assistant','Management Information Systems (MIS)',1,4,'Student Assistant','On-Campus','Main Campus · ICT Center 302','₱85.00 / hour','Hourly','15 - 20 hrs/week',5,5,3,'2026-11-15','active','assets/img/jobs/job-01.jpg','[\"Flexible Schedule\",\"Urgent\",\"Tech Support\",\"University Office\"]','[\"Student Assistant\",\"Flexible Schedule\",\"Urgent\"]','Assist the MIS team in maintaining student computer laboratories, performing routine hardware/software troubleshooting, monitoring laboratory usage, and assisting students during hands-on classes.','[\"Check PC hardware and peripheral operability before daily lab sessions.\",\"Assist students and professors with network login, compiler installations, and software tools.\",\"Maintain cleanliness and enforce lab safety regulations.\",\"Log hardware faults and escalate critical network disruptions to senior network engineers.\"]','[\"Currently enrolled 2nd to 4th year BSIS, BSCS, or BSDS student.\",\"General Weighted Average (GWA) of 2.25 or better.\",\"Basic knowledge in PC troubleshooting, Windows\\/Linux OS, and local networking.\",\"Responsible, punctual, and equipped with strong interpersonal skills.\"]',0,NULL,'2026-08-20 00:00:00','2026-09-30 20:24:12'),(2,'Student Records & Archival Assistant','Office of the University Registrar',3,3,'Student Assistant','On-Campus','Admin Building · Room 104','₱80.00 / hour','Hourly','10 - 15 hrs/week',4,4,2,'2026-11-20','active','assets/img/jobs/job-02.jpg','[\"Part-Time\",\"Office Work\",\"University Office\"]','[\"Student Assistant\",\"Part-time\"]','Support the University Registrar in organizing student records, encoding registration documents, sorting physical course binders, and assisting visitors at the information desk.','[\"Scan and index student transcript documents into the digital archive.\",\"Assist in receiving and sorting incoming student clearance and graduation applications.\",\"Organize student physical 201 filing cabinets.\",\"Provide courteous frontline queue direction during peak enrollment periods.\"]','[\"Open to all undergraduate programs in good standing.\",\"Proficient in Microsoft Excel, Word, and Google Workspace.\",\"High attention to detail and strong adherence to data privacy and confidentiality.\",\"Must have at least 3 consecutive free hours during weekdays.\"]',0,NULL,'2026-08-21 00:00:00','2026-09-30 20:24:12'),(3,'Digital Cataloging & Library Aid','University Library Services',2,3,'Student Assistant','On-Campus','Library Wing · 2nd Floor','₱80.00 / hour','Hourly','12 - 18 hrs/week',3,3,1,'2026-11-25','active','assets/img/jobs/job-03.jpg','[\"Quiet Environment\",\"Study Friendly\",\"University Office\"]','[\"Student Assistant\",\"Flexible Schedule\"]','Assist librarians with book circulation, Dewey Decimal sorting, barcode scanning, thesis collection archiving, and patron assistance in the quiet study hub.','[\"Check in and check out library reference books using the barcode circulation scanner.\",\"Shelve books according to cataloging standards and perform shelf-reading.\",\"Assist students and faculty in navigating OPAC (Online Public Access Catalog).\",\"Monitor study areas to ensure a conducive, quiet learning atmosphere.\"]','[\"Bona fide student with at least 1 remaining academic year.\",\"Diligent, polite, organized, and fond of reading and books.\",\"Can commit to either morning (8:00 AM - 12:00 PM) or afternoon (1:00 PM - 5:00 PM) shifts.\"]',0,NULL,'2026-08-22 00:00:00','2026-09-30 20:24:12'),(4,'Peer Tutor - Linear Algebra & Discrete Math','Institute of Science and Mathematics (ISM)',5,5,'Student Assistant','On-Campus','Math Learning Center · Room 215','₱100.00 / hour','Hourly','8 - 12 hrs/week',3,3,1,'2026-11-30','active','assets/img/jobs/job-04.jpg','[\"High Pay\",\"Academic Coaching\",\"Peer Mentoring\"]','[\"Peer Tutor\",\"High Pay\",\"Academic Coaching\"]','Provide one-on-one and small group tutoring assistance to freshmen and sophomores taking Linear Algebra, Discrete Structures, and Calculus I.','[\"Conduct structured problem-solving sessions for struggling students.\",\"Explain abstract proofs, matrix operations, and recurrence relations clearly.\",\"Review lecture materials and prepare practice worksheets.\",\"Submit weekly student attendance and progress logs to the department coordinator.\"]','[\"Completed Linear Algebra and Discrete Math with a grade of 1.50 or higher.\",\"Patient, articulate, and dedicated to helping peers succeed.\",\"Recommended by at least one mathematics faculty instructor.\"]',0,NULL,'2026-08-23 00:00:00','2026-09-30 20:24:12'),(5,'Junior Web Developer & QA Assistant','TechVanguard Solutions Inc.',1,6,'Part-Time','Hybrid','Dasma Tech Park · Suite 401 & Remote','₱120.00 / hour','Hourly','15 - 20 hrs/week',2,2,1,'2026-12-01','active','assets/img/jobs/job-05.jpg','[\"Hybrid\",\"High Pay\",\"Industry Partner\",\"Accredited Partner\"]','[\"Industry Partner\",\"High Pay\",\"Hybrid Setup\"]','Work with our software engineering squad to build responsive front-end components, write automated unit tests, and inspect web applications for responsive design bugs.','[\"Implement responsive UI slices using HTML5, CSS3\\/Tailwind, and vanilla JavaScript.\",\"Conduct exploratory cross-browser testing on mobile, tablet, and desktop viewports.\",\"Log reproducible defect reports with clear reproduction steps in Jira.\",\"Collaborate during bi-weekly sprint planning and code reviews.\"]','[\"3rd or 4th Year BSCS, BSIS, or BSECE student.\",\"Familiarity with Git version control, GitHub workflows, and modern web standards.\",\"Knowledge of JavaScript (ES6+), CSS Flexbox\\/Grid, and responsive layout principles.\",\"Self-starter with good communication skills for hybrid team collaboration.\"]',0,NULL,'2026-08-24 00:00:00','2026-09-30 20:24:12'),(6,'Multimedia Content & Video Assistant','Dasma Creative Media Studio',3,7,'Part-Time','Hybrid','Creative Hub Center · Studio 201','₱95.00 / hour','Hourly','12 - 16 hrs/week',2,2,1,'2026-12-15','active','assets/img/jobs/job-06.jpg','[\"Creative\",\"Graphic Design\",\"Video Editing\",\"Accredited Partner\"]','[\"Industry Partner\",\"Creative Work\",\"Flexible Schedule\"]','Assist creative directors in producing campus digital flyers, short-form video reels, and promotional photo assets for social media and university broadcasts.','[\"Edit short vertical videos (TikTok\\/Reels format) showcasing campus highlights and events.\",\"Design clean promotional graphics using Canva, Adobe Photoshop, or Figma.\",\"Organize digital asset libraries and maintain media file nomenclature standards.\",\"Provide production assistance during studio and campus on-location shoots.\"]','[\"Portfolio or sample links demonstrating graphic design or video editing work.\",\"Proficiency in CapCut, Premiere Pro, Photoshop, or Figma.\",\"Creative mindset with strong sense of typography, pacing, and color palette.\",\"Open to 2nd to 4th year students across all degree programs.\"]',0,NULL,'2026-08-25 00:00:00','2026-09-30 20:24:12'),(7,'Campus Student Barista & Cafe Cashier','Campus Food Concessionaire Partner',3,8,'Student Assistant','On-Campus','University Student Pavilion & Food Arcade','₱90.00 / hour','Hourly','10 - 15 hrs/week',3,3,1,'2026-12-20','active','assets/img/jobs/job-07.jpg','[\"Part-Time\",\"Customer Service\",\"On-Campus\",\"Accredited Partner\"]','[\"Part-Time Job\",\"On-Campus\",\"Flexible Schedule\"]','Learn specialty espresso brewing, assist in counter POS cashiering, and provide friendly hospitality at the official campus student cafe located inside the Student Pavilion.','[\"Prepare espresso drinks, cold brews, and seasonal refreshments following recipes.\",\"Operate touch-screen point-of-sale register and issue official receipts.\",\"Maintain strict cleanliness and food safety sanitation in the dining area.\",\"Coordinate with supervisor for weekly shift planning aligned with class schedules.\"]','[\"Cheerful, friendly demeanor with strong work ethic.\",\"No prior barista experience required; complete paid on-site training provided.\",\"Available for morning (7:30 AM - 11:30 AM) or afternoon (1:30 PM - 5:30 PM) slots.\"]',0,NULL,'2026-08-26 00:00:00','2026-09-30 20:24:12'),(8,'Science & Computer Lab Assistant','College of Science & Nursing Skills Labs',4,24,'Student Assistant','On-Campus','Science Wing · Lab 101','₱85.00 / hour','Hourly','12 - 16 hrs/week',4,4,2,'2026-12-10','active','assets/img/jobs/job-08.jpg','[\"Science\",\"Lab Prep\",\"University Office\"]','[\"Student Assistant\",\"Urgent\"]','Assist laboratory custodians in preparing glassware, non-hazardous reagent solutions, setting up microscope benches, and conducting equipment sanitation.','[\"Distribute apparatus to students before experiments and inspect returns for breakage.\",\"Wash and autoclave laboratory glassware following strict chemical hygiene procedures.\",\"Maintain reagent inventory and log chemical consumption.\",\"Ensure proper waste segregation and disposal compliance.\"]','[\"Enrolled in Allied Science, Computer, or Engineering programs.\",\"Passed Chemistry\\/Lab fundamentals with high marks.\",\"Strict compliance with lab safety goggles, lab coat, and chemical handling guidelines.\"]',0,NULL,'2026-08-25 00:00:00','2026-09-30 20:24:12'),(9,'Gymnasium Equipment Custodian & Court Monitor','Athletics & Sports Development Unit',6,25,'Student Assistant','On-Campus','Campus Gymnasium & Sports Complex','₱85.00 / hour','Hourly','10 - 15 hrs/week',3,3,1,'2026-11-30','active','assets/img/jobs/job-09.jpg','[\"Sports\",\"Equipment Logistics\",\"University Office\",\"On-Campus\"]','[\"Student Assistant\",\"Flexible Schedule\"]','Assist the Athletics & Sports Development Office in issuing and logging sports equipment, monitoring gymnasium court reservations, ensuring court safety regulations, and maintaining equipment cleanliness.','[\"Inspect and distribute balls, nets, and athletics equipment before varsity practice and intramural games.\",\"Maintain digital check-in\\/check-out logs for student equipment borrowings.\",\"Monitor court bookings and enforce footwear and gymnasium safety rules.\",\"Report damaged equipment and assist in periodic inventory audits.\"]','[\"Currently enrolled KLD student in good academic standing.\",\"Punctual, physically active, and responsible with university property.\",\"Available for afternoon shifts (1:00 PM - 5:00 PM) or weekend sports events.\",\"Previous involvement in sports or athletics is an advantage but not required.\"]',0,NULL,'2026-08-27 00:00:00','2026-09-30 20:24:12'),(10,'Intramural Tournament Scorekeeper & Athletics Aide','Athletics & Sports Development Unit',6,25,'Student Assistant','On-Campus','University Covered Courts & Field','₱85.00 / hour','Hourly','8 - 12 hrs/week',2,2,0,'2026-12-05','active','assets/img/jobs/job-10.jpg','[\"Scorekeeper\",\"Intramurals\",\"University Office\",\"High Pay\"]','[\"Student Assistant\",\"Part-Time\",\"Flexible Schedule\"]','Support campus sports tournaments and intramural leagues through official digital scorekeeping, scoreboard operation, equipment staging, and referee table coordination.','[\"Operate the electronic scoreboard and official timer during scheduled tournament matches.\",\"Record points, fouls, timeouts, and player statistics on official score sheets.\",\"Coordinate with game officials and tournament directors to ensure smooth match flow.\",\"Assist in trophy staging, court setup, and post-game record filing.\"]','[\"Enrolled student with GWA of 2.50 or better.\",\"High focus, attention to detail, and familiarity with basketball, volleyball, or badminton rules.\",\"Ability to work calmly under the excitement of live competitive games.\",\"Willing to work flexible schedules during intramural tournament weeks.\"]',0,NULL,'2026-08-28 00:00:00','2026-09-30 20:24:12'),(11,'Peer Tutor - Data Structures & Algorithms (Java/Python)','Management Information Systems (MIS)',5,4,'Student Assistant','On-Campus','Tech Building · Coding Commons 308','₱100.00 / hour','Hourly','10 - 15 hrs/week',2,2,1,'2026-11-28','active','assets/img/jobs/job-11.jpg','[\"Peer Tutor\",\"Coding\",\"DSA\",\"Python\",\"Java\"]','[\"Peer Tutor\",\"High Pay\",\"Academic Coaching\"]','Mentor 1st and 2nd year computing students in linked lists, trees, graph traversals, and algorithmic complexity in Java and Python.','[\"Hold drop-in coding consultation hours at the Tech Building learning commons.\",\"Guide students through debugging and algorithmic problem formulation without giving solutions.\",\"Prepare weekly coding review problems aligned with instructor syllabus.\",\"Track attendee progress and coordinate with faculty instructors.\"]','[\"3rd or 4th Year BSCS or BSIS student with GWA of 1.75 or better in DSA courses.\",\"Strong command of Java, Python, or C++ and clear instructional ability.\",\"Patience and passion for helping fellow peers develop solid programming logic.\"]',0,NULL,'2026-09-01 09:00:00','2026-09-30 20:24:12'),(12,'Nursing Skills & Simulation Lab Aide','College of Science & Nursing Skills Labs',4,24,'Student Assistant','On-Campus','Allied Health Wing · Simulation Ward 202','₱85.00 / hour','Hourly','12 - 16 hrs/week',3,3,1,'2026-12-05','active','assets/img/jobs/job-12.jpg','[\"Nursing\",\"Simulation Ward\",\"Health Sciences\",\"Laboratory\"]','[\"Student Assistant\",\"Healthcare\",\"On-Campus\"]','Support clinical instructors in setting up patient simulation manikins, medical equipment trays, sterile gloves, and vitals monitoring stations.','[\"Stage clinical ward beds, IV stands, and simulator manikins prior to OSCE clinical exams.\",\"Manage medical consumable inventory (bandages, syringes, PPE, antiseptic supplies).\",\"Disinfect simulation equipment following institutional biosafety guidelines.\",\"Log student clinical laboratory attendance and room reservations.\"]','[\"Currently enrolled 2nd to 4th year BS Nursing or Midwifery student.\",\"Strong adherence to medical hygiene, infection control, and clinical protocol.\",\"Dependable, methodical, and attentive to equipment upkeep.\"]',0,NULL,'2026-09-02 10:30:00','2026-09-30 20:24:12'),(13,'Student Guidance Frontdesk & Peer Facilitator','Guidance & Counseling Center',3,22,'Student Assistant','On-Campus','Student Center · Room 204','₱80.00 / hour','Hourly','10 - 14 hrs/week',2,2,1,'2026-11-20','active','assets/img/jobs/job-13.jpg','[\"Counseling\",\"Frontline\",\"Mental Health\",\"Peer Facilitation\"]','[\"Student Assistant\",\"Support Services\"]','Welcoming students to the Guidance Center, assisting with counseling appointment bookings, preparing psychometric testing packets, and supporting mental health awareness drives.','[\"Greet students warmly and handle confidential appointment scheduling.\",\"Prepare standardized testing materials and tally psychological inventory scores.\",\"Assist in organizing campus Mental Health Week activities and wellness seminars.\",\"Strictly observe Data Privacy Act (RA 10173) concerning student counseling records.\"]','[\"2nd to 4th year BS Psychology or BA Communication student preferred.\",\"Warm, empathetic demeanor with exceptional discretion and confidentiality.\",\"Good organizational skills and proficiency in Google Forms and Docs.\"]',0,NULL,'2026-09-03 08:45:00','2026-09-30 20:24:12'),(14,'Campus Scholarship Records & Encoding Clerk','Admissions & Scholarship Office',3,26,'Student Assistant','On-Campus','Admin Building · Ground Floor','₱80.00 / hour','Hourly','12 - 15 hrs/week',3,3,2,'2026-11-18','active','assets/img/jobs/job-14.jpg','[\"Scholarships\",\"Data Encoding\",\"Admin Building\",\"Frontline\"]','[\"Student Assistant\",\"Office Work\"]','Support scholarship coordinators in evaluating applicant documentary requirements, validating GWA grades, and encoding LGU scholarship grantee records.','[\"Verify completeness of incoming city scholarship grant forms and grade slips.\",\"Encode student applicant records into the scholarship database spreadsheet.\",\"Answer student queries regarding renewal deadlines and documentary prerequisites.\",\"Assist in preparing official scholarship payroll lists for stipend disbursement.\"]','[\"Open to all undergraduate students in good academic standing.\",\"High proficiency in MS Excel \\/ Google Sheets and fast 10-key numeric typing.\",\"Attention to detail and polite interpersonal telephone and counter etiquette.\"]',0,NULL,'2026-09-04 11:00:00','2026-09-30 20:24:12'),(15,'Junior Frontend Web Assistant (React / CSS)','Software & Web Development Partner',1,6,'Part-Time','Hybrid','Dasma Tech Park · 4th Floor','₱120.00 / hour','Hourly','15 - 20 hrs/week',2,2,1,'2026-12-08','active','assets/img/jobs/job-15.jpg','[\"Web Development\",\"React\",\"Frontend\",\"High Pay\",\"Accredited Partner\"]','[\"Industry Partner\",\"High Pay\",\"Hybrid\"]','Join an agile engineering team building web applications for regional clients. Perfect for students looking for real-world production code experience.','[\"Convert Figma design wireframes into responsive modular HTML\\/CSS\\/React components.\",\"Write basic Cypress or Playwright end-to-end user tests for client workflows.\",\"Participate in weekly sprint sync meetings and Git pull request reviews.\"]','[\"Demonstrated proficiency in JavaScript (ES6+), React or Vue, and modern CSS.\",\"Active GitHub profile with personal or coursework projects.\",\"Ability to dedicate 15 hours per week without conflicting with class schedules.\"]',0,NULL,'2026-09-05 13:30:00','2026-09-30 20:24:12'),(16,'Creative Graphics & Social Media Assistant','Creative & Digital Media Partner',3,7,'Part-Time','Hybrid','Creative Hub Center · Suite 201','₱95.00 / hour','Hourly','12 - 16 hrs/week',2,2,2,'2026-11-10','active','assets/img/jobs/job-16.jpg','[\"Design\",\"Graphics\",\"Social Media\",\"Accredited Partner\",\"Filled\"]','[\"Industry Partner\",\"Filled Quota\",\"Creative\"]','Assist our creative team with social media copywriting, layout design for campus infographics, and brand asset management.','[\"Produce eye-catching visual banners for Facebook, Instagram, and LinkedIn.\",\"Write engaging captions following brand voice guidelines.\",\"Schedule and monitor post engagement analytics.\"]','[\"Solid graphic portfolio using Canva, Adobe Illustrator, or Photoshop.\",\"Good English and Filipino written communication skills.\",\"Enrolled 2nd or 3rd year student in BACOMM, BSHM, or ICDI.\"]',0,NULL,'2026-09-06 09:15:00','2026-09-30 20:24:12'),(17,'Bookstore Inventory & POS Cashier Aide','Campus Bookstore & Retail Partner',3,27,'Student Assistant','On-Campus','Commercial Arcade · Unit 105','₱85.00 / hour','Hourly','12 - 16 hrs/week',2,2,0,'2026-12-15','active','assets/img/jobs/job-17.jpg','[\"Bookstore\",\"Cashier\",\"Inventory\",\"Retail\",\"On-Campus\"]','[\"Student Assistant\",\"On-Campus\",\"Retail\"]','Assist in receiving textbook deliveries, shelf stocking, barcode pricing, and friendly counter cashiering at the on-campus bookstore.','[\"Operate point-of-sale cash register and issue itemized receipts.\",\"Unpack textbook boxes, verify shipment invoices, and affix barcode tags.\",\"Keep academic textbook shelves neatly organized by college and subject code.\",\"Assist students and faculty in locating required course syllabi materials.\"]','[\"Bona fide student with honest, dependable, and pleasant personality.\",\"Basic math and cashiering accuracy.\",\"Available for shifts during weekday morning or lunch hours.\"]',0,NULL,'2026-09-07 10:00:00','2026-09-30 20:24:12'),(18,'Campus Health Clinic & First Aid Support Aide','College of Science & Nursing Skills Labs',4,24,'Student Assistant','On-Campus','Main Clinic · Health Services Wing','₱85.00 / hour','Hourly','10 - 14 hrs/week',2,2,1,'2026-11-25','active','assets/img/jobs/job-18.jpg','[\"Clinic\",\"First Aid\",\"Health Services\",\"Nursing\",\"On-Campus\"]','[\"Student Assistant\",\"Healthcare\"]','Assist the university registered nurses with patient queue registration, temperature/BP checks, medicine cabinet inventory, and first-aid standby during campus gatherings.','[\"Record student and employee vital signs in clinic logbooks.\",\"Prepare basic first-aid kits and check expiration dates of over-the-counter medicine.\",\"Provide standby assistance during university sports meets and outdoor events.\",\"Maintain clinic sanitization and rest-bed linen freshness.\"]','[\"Currently enrolled 2nd to 4th year BS Nursing, Midwifery, or Psychology student.\",\"Certified in Basic Life Support (BLS) or First Aid is an advantage.\",\"Compassionate, composed under emergencies, and reliable.\"]',0,NULL,'2026-09-08 14:00:00','2026-09-30 20:24:12'),(19,'Varsity Intramural Field Marshal & Athletics Aide','Athletics & Sports Development Unit',6,25,'Student Assistant','On-Campus','University Track Oval & Grandstand','₱85.00 / hour','Hourly','8 - 12 hrs/week',3,3,1,'2026-12-10','active','assets/img/jobs/job-19.jpg','[\"Athletics\",\"Field Marshal\",\"Intramurals\",\"Sports Complex\"]','[\"Student Assistant\",\"Athletics\"]','Direct field logistics, enforce spectator boundary rules, manage hydration coolers, and coordinate tournament schedules for inter-institute competitions.','[\"Set up cones, timing gates, and boundary ropes prior to track and football matches.\",\"Manage ice and water hydration stations for competing varsity and collegiate athletes.\",\"Coordinate team rosters and signal warm-up call times.\",\"Assist tournament referees with line calling and score certification.\"]','[\"Energetic student with enthusiasm for sports and outdoor event management.\",\"Good voice projection and authority to enforce spectator safety boundaries.\",\"Available on Friday afternoons and Saturday tournament mornings.\"]',0,NULL,'2026-09-09 09:30:00','2026-09-30 20:24:12'),(20,'Technical Customer Care Student Intern','Customer Experience & BPO Partner',1,28,'Part-Time','Hybrid','Robinsons Dasma Tech Wing · 3rd Floor','₱110.00 / hour','Hourly','16 - 20 hrs/week',4,4,2,'2026-12-18','active','assets/img/jobs/job-20.jpg','[\"Customer Care\",\"Tech Support\",\"High Pay\",\"Night Shift Allowed\"]','[\"Industry Partner\",\"High Pay\",\"Flexible Shifts\"]','Answer technical support tickets via email, web chat, and voice calls for international software users. Offers flexible 4-hour micro-shifts tailored around college class schedules.','[\"Handle tier-1 software troubleshooting via omnichannel ticketing system (Zendesk).\",\"Guide users through password resets, configuration settings, and billing queries.\",\"Document issue resolution steps and maintain internal knowledge base articles.\",\"Adhere to quality assurance standards and customer satisfaction targets.\"]','[\"2nd to 4th year student with excellent English verbal and written communication.\",\"Fast typing speed (at least 40 WPM) and comfortable with computer multitasking.\",\"Willing to undergo 2 weeks of paid virtual onboarding.\"]',0,NULL,'2026-09-10 11:00:00','2026-09-30 20:24:12');
