INSERT INTO `notifications` VALUES (1,1,'interview','Interview Scheduled: Computer Lab Assistant','Engr. Clara Villanueva has scheduled your interview on 2026-09-28 at 02:00 PM at KLD Tech Building, Room 305.','student/my-applications.php','bi-calendar-check','info',0,'2026-09-24 10:00:00'),(2,1,'shortlist','Application Shortlisted!','TechVanguard Solutions Inc. shortlisted your application for Junior Frontend Web Assistant.','student/my-applications.php','bi-patch-check','success',0,'2026-09-23 16:30:00'),(3,2,'job_offer','Congratulations! You\'re Hired 🎉','University Library Services has accepted your application for Digital Cataloging & Library Aid.','student/my-applications.php','bi-award-fill','success',1,'2026-08-24 16:20:00'),(4,11,'job_offer','Officially Hired: Nursing Skills Lab Aide','Prof. Corazon Navarro has approved your assistantship for 1st Semester Simulation Ward duty.','student/my-applications.php','bi-heart-pulse-fill','success',0,'2026-09-08 14:30:00'),(5,11,'interview','Interview Scheduled: Campus Clinic','Your interview for Campus Health Clinic Support Aide is set for 2026-09-30 at 09:00 AM.','student/my-applications.php','bi-calendar-event','info',0,'2026-09-18 11:15:00'),(6,13,'job_offer','Application Accepted: Student Records Assistant','The Office of the University Registrar has approved your appointment.','student/my-applications.php','bi-check-circle-fill','success',1,'2026-09-14 11:30:00'),(7,15,'job_offer','Creative Content Offer Accepted!','Dasma Creative Media Studio approved your application for Multimedia Content Assistant.','student/my-applications.php','bi-camera-reels-fill','success',0,'2026-09-11 17:00:00'),(8,16,'job_offer','Welcome to Campus Cafe & Co.!','Chef Patricia Reyes has accepted your application for Student Barista. Orientation begins Friday.','student/my-applications.php','bi-cup-hot-fill','success',0,'2026-09-10 16:45:00'),(9,17,'job_offer','Hired: Guidance Peer Facilitator','Welcome to the Guidance team! Your assistantship has been confirmed by Dr. Evelyn Ramos.','student/my-applications.php','bi-people-fill','success',0,'2026-09-12 11:00:00'),(10,18,'job_offer','Appointed: Lead DSA Peer Tutor','Engr. Clara Villanueva officially designated you as Lead Peer Tutor for Data Structures & Algorithms.','student/my-applications.php','bi-code-slash','success',1,'2026-09-09 10:00:00'),(11,10,'job_offer','Appointed: Senior Student Lab Lead','Your appointment for Computer Lab Technical Assistant has been confirmed.','student/my-applications.php','bi-laptop-fill','success',0,'2026-09-01 10:00:00'),(12,3,'new_applicant','New Applicant: Student Records Assistant','Juan Dela Cruz has submitted an application for Student Records & Archival Assistant.','employer/applicants.php','bi-person-plus-fill','primary',1,'2026-08-24 09:15:00'),(13,4,'new_applicant','New Application: Joshua Garcia','Joshua Garcia (1st Year BSIT) submitted an application for Computer Lab Technical Assistant.','employer/applicants.php','bi-person-plus','primary',0,'2026-09-05 10:15:00'),(14,4,'system','Monthly Assistantship Timesheet Audit','Please submit certified biometric or attendance logs for student assistants before the 30th.','employer/dashboard.php','bi-clock-history','warning',0,'2026-09-20 08:00:00'),(15,6,'new_applicant','New Candidate: Gabriel Tan','Gabriel Tan applied for Junior Web Developer & QA Assistant.','employer/applicants.php','bi-person-badge','primary',1,'2026-09-10 11:20:00'),(16,25,'new_applicant','New Candidate: Ethan Vance Reyes','Ethan Vance Reyes applied for Gymnasium Equipment Custodian.','employer/applicants.php','bi-person-plus','primary',0,'2026-09-12 11:45:00'),(17,5,'accreditation','Partner Registration Pending: Apex Robotics','Apex Robotics & Automation PH Corp. submitted accreditation documents awaiting your review.','admin/users.php','bi-building-exclamation','warning',0,'2026-09-23 08:30:00'),(18,5,'verification','Student Document Pending: Ralph Matthew Santos','Ralph Matthew Santos